# Judgement fields for run 0046, QAA Frameworks 2024 (FHEQ and FQHEIS), stage 1: the qualification descriptors 4.10 to 4.18. std.
Q = {  # descriptor: (level ids, qualification as the student would name it, short)
 '4.10': (['fheq:4'], 'a Certificate of Higher Education', 'CertHE (FHEQ 4)'),
 '4.11': (['fqheis:7'], 'a Certificate of Higher Education in Scotland', 'CertHE (SCQF 7)'),
 '4.12': (['fheq:5'], 'a foundation degree', 'foundation degree (FHEQ 5)'),
 '4.13': (['fqheis:8'], 'a Diploma of Higher Education in Scotland', 'DipHE (SCQF 8)'),
 '4.14': (['fqheis:9'], 'a bachelor\'s degree without honours in Scotland', 'bachelor\'s non-honours (SCQF 9)'),
 '4.15': (['fheq:6'], 'a bachelor\'s degree with honours', 'honours degree (FHEQ 6)'),
 '4.16': (['fqheis:10'], 'a bachelor\'s degree with honours in Scotland', 'honours degree (SCQF 10)'),
 '4.17': (['fheq:7', 'fqheis:11'], 'a master\'s degree', 'master\'s (FHEQ 7, SCQF 11)'),
 '4.18': (['fheq:8', 'fqheis:12'], 'a doctorate', 'doctorate (FHEQ 8, SCQF 12)'),
}
P = {}
def s(i, verbs, about, para, prac, ben): P[i] = dict(verbs=verbs, about=about, para=para, prac=prac, ben=ben)

# 4.10 CertHE, FHEQ 4
s('4.10.b1', ['evaluate', 'interpret'], 'underlying concepts and their interpretation', 'Knows the concepts and principles beneath their area of study and can judge and read them within it.', 'CertHE holders have shown they know the concepts and principles underneath their area and can evaluate and interpret them there.', 'To be awarded a Certificate of Higher Education, you will have shown that you know the main ideas and principles behind your subject and can weigh them up within it.')
s('4.10.b2', ['present', 'evaluate', 'interpret', 'develop', 'make'], 'handling data to argue and judge', 'Can present and weigh qualitative and quantitative data to build arguments and reach sound judgements grounded in the subject\'s basic theories.', 'CertHE holders have shown they can present and assess numbers and qualitative data to build arguments and judge soundly from basic subject theory.', 'To be awarded a Certificate of Higher Education, you will have shown that you can present and weigh up data, numbers and words alike, to make an argument and a sound judgement.')
s('4.10.b3', ['evaluate'], 'judging approaches to problems', 'Weighs how well different approaches suit problems in their study or work.', 'Typical CertHE holders will be able to judge which approaches suit a problem in their study or work.', 'With a Certificate of Higher Education, you will usually be able to judge which ways of tackling a problem fit best.')
s('4.10.b4', ['communicate'], 'communicating results soundly', 'Reports what their study or work found, accurately, reliably and in a structured, coherent way.', 'Typical CertHE holders will be able to report their results accurately and reliably, in structured, coherent argument.', 'With a Certificate of Higher Education, you will usually be able to report what you found accurately, in a clear and well-ordered argument.')
s('4.10.b5', ['undertake', 'develop'], 'further training in a managed setting', 'Takes on more training and new skills where the setting is structured and managed.', 'Typical CertHE holders will be able to take further training and learn new skills in a structured, managed setting.', 'With a Certificate of Higher Education, you will usually be able to go on training and learning new skills where the setting is well organised.')
s('4.10.b6', [], 'qualities for work with some personal responsibility', 'Has the qualities and transferable skills for jobs that call for some personal responsibility.', 'CertHE holders will have the qualities and transferable skills for work that asks for some personal responsibility.', 'With a Certificate of Higher Education, you will have the qualities and skills for work where you carry some responsibility yourself.')
# 4.11 CertHE, SCQF 7
s('4.11.b1', [], 'outline of the subject, some areas in more depth', 'Knows the scope and main areas of the subject in outline, how it links to related subjects, and some key areas more fully.', 'Scottish CertHE holders have shown outline knowledge of the subject\'s scope, main areas and neighbours, with fuller knowledge of some key areas.', 'To be awarded a Certificate of Higher Education in Scotland, you will have shown that you know the outline of your subject and its neighbours, and some key areas in more depth.')
s('4.11.b2', [], 'major theories and concepts', 'Understands the subject\'s major theories, principles and concepts.', 'Scottish CertHE holders have shown understanding of the major theories, principles and concepts.', 'To be awarded a Certificate of Higher Education in Scotland, you will have shown that you understand the main theories and ideas of your subject.')
s('4.11.b3', [], 'familiarity with routine materials and practices', 'Is familiar with some of the subject\'s routine materials, techniques and practices.', 'Scottish CertHE holders have shown familiarity with some routine materials, techniques and practices of the subject.', 'To be awarded a Certificate of Higher Education in Scotland, you will have shown that you know your way round some of the subject\'s everyday materials and methods.')
s('4.11.b4', ['include'], 'gathering and presenting routine information', 'Has the skills to gather, analyse at a basic level and present routine information, ideas and data within a clearly set context, using ICT where it suits the subject.', 'Scottish CertHE holders have shown skills in gathering, basic analysis and presenting routine information and data in a clearly defined context, ICT included as the subject needs.', 'To be awarded a Certificate of Higher Education in Scotland, you will have shown that you can gather, sort and present routine information and data, using digital tools where they fit.')
s('4.11.b5', ['use', 'evaluate', 'formulate'], 'routine use of knowledge on routine problems', 'Uses subject knowledge and technique routinely to weigh and build arguments and answers to routine problems.', 'Typical Scottish CertHE holders will be able to use subject knowledge and techniques routinely to evaluate and build arguments and solutions to routine problems.', 'With a Certificate of Higher Education in Scotland, you will usually be able to use what you know to weigh up and answer everyday problems in your subject.')
s('4.11.b6', ['communicate'], 'communicating results soundly', 'Reports the results of study and other work accurately and reliably, in structured, coherent argument.', 'Typical Scottish CertHE holders will be able to report results accurately and reliably, in structured, coherent argument.', 'With a Certificate of Higher Education in Scotland, you will usually be able to report what you found accurately and in a clear order.')
s('4.11.b7', ['undertake'], 'further learning in a managed setting', 'Goes on learning where the setting is structured and managed.', 'Typical Scottish CertHE holders will be able to continue learning in a structured, managed setting.', 'With a Certificate of Higher Education in Scotland, you will usually be able to keep learning where the setting is well organised.')
s('4.11.b8', ['apply'], 'skills where decisions are well defined', 'Applies subject and transferable skills where personal responsibility is limited and the task and its decision criteria are clearly set.', 'Typical Scottish CertHE holders will be able to apply subject and transferable skills where responsibility is limited and the task\'s scope and decision criteria are well defined.', 'With a Certificate of Higher Education in Scotland, you will usually be able to use your skills on tasks that are clearly set out, carrying a little responsibility yourself.')
# 4.12 foundation degree, FHEQ 5
s('4.12.b1', [], 'critical understanding of established principles', 'Knows and critically understands the field\'s well-established principles and how they came about.', 'Foundation degree holders have shown knowledge and critical understanding of the field\'s established principles and how they developed.', 'To be awarded a foundation degree, you will have shown that you know and can think critically about your field\'s established principles and where they came from.')
s('4.12.b2', ['apply'], 'applying principles beyond their first context', 'Can apply core concepts and principles outside the setting where they were learned, at work where that fits.', 'Foundation degree holders have shown they can apply core concepts and principles beyond where they first met them, including at work where relevant.', 'To be awarded a foundation degree, you will have shown that you can use core ideas in new settings, including at work where it fits.')
s('4.12.b3', ['evaluate', 'solving'], 'methods of enquiry and judging approaches', 'Knows the subject\'s main methods of enquiry and can judge critically how well different approaches suit its problems.', 'Foundation degree holders have shown knowledge of the main methods of enquiry and can evaluate critically which approaches suit the field\'s problems.', 'To be awarded a foundation degree, you will have shown that you know your subject\'s main research methods and can judge which approach suits a problem.')
s('4.12.b4', ['influences'], 'the limits of one\'s own knowledge', 'Understands where their knowledge stops and how that shapes analysis and interpretation built on it.', 'Foundation degree holders have shown they understand the limits of their knowledge and how these shape their analysis and interpretation.', 'To be awarded a foundation degree, you will have shown that you know where your knowledge ends and how that affects your conclusions.')
s('4.12.b5', ['use', 'initiate', 'undertake', 'propose'], 'critical analysis and proposing solutions', 'Uses a range of established techniques to start and carry out critical analysis of information and to propose answers to the problems it shows.', 'Typical foundation degree holders will be able to use established techniques to begin and carry out critical analysis and propose solutions from it.', 'With a foundation degree, you will usually be able to use proven techniques to analyse information critically and suggest solutions to the problems you find.')
s('4.12.b6', ['communicate', 'deploy'], 'communicating to specialist and general audiences', 'Communicates information, argument and analysis in several forms to specialist and general audiences, and uses the discipline\'s key techniques well.', 'Typical foundation degree holders will be able to communicate information, arguments and analysis in varied forms to specialists and non-specialists, and use key discipline techniques well.', 'With a foundation degree, you will usually be able to explain information and arguments in different forms to experts and non-experts, and use your subject\'s key techniques well.')
s('4.12.b7', ['undertake', 'develop', 'acquire', 'enable', 'assume'], 'further training towards significant responsibility', 'Undertakes further training, builds on existing skills and gains new competences that equip them for significant responsibility in organisations.', 'Typical foundation degree holders will be able to take further training, build skills and gain new competences that prepare them for significant responsibility at work.', 'With a foundation degree, you will usually be able to keep training and build new skills that prepare you for real responsibility in an organisation.')
s('4.12.b8', [], 'qualities for work with responsibility and decisions', 'Has the qualities and transferable skills for jobs that call for personal responsibility and decision-making.', 'Foundation degree holders will have the qualities and transferable skills for work needing personal responsibility and decision-making.', 'With a foundation degree, you will have the qualities and skills for work where you take responsibility and make decisions.')
# 4.13 DipHE, SCQF 8
s('4.13.b1', ['include'], 'scope of the subject, detail in key areas, current issues', 'Knows and understands the subject\'s scope and main areas and its links to others, with detail in some key areas, possibly including current issues in a few specialised ones.', 'Scottish DipHE holders have shown knowledge of the subject\'s scope and main areas and links, detail in key areas and some awareness of current issues in specialised areas.', 'To be awarded a Diploma of Higher Education in Scotland, you will have shown that you know the shape of your subject, some key areas in detail and something of current debates.')
s('4.13.b2', [], 'essential theories and issues at the forefront', 'Is familiar with and understands a range of essential theories, principles and concepts, and is aware of major issues at the subject\'s forefront.', 'Scottish DipHE holders have shown understanding of a range of essential theories and concepts and awareness of major issues at the forefront.', 'To be awarded a Diploma of Higher Education in Scotland, you will have shown that you understand the essential theories of your subject and know the big questions at its leading edge.')
s('4.13.b3', [], 'effective use of essential materials and practices', 'Is familiar with the subject\'s essential and routine materials, techniques and practices and uses them effectively.', 'Scottish DipHE holders have shown familiarity with essential and routine materials, techniques and practices and use them effectively.', 'To be awarded a Diploma of Higher Education in Scotland, you will have shown that you use your subject\'s essential materials and methods well.')
s('4.13.b4', ['include'], 'critical gathering and presentation of core information', 'Has skills to gather, analyse critically and present the information, ideas and data at the subject\'s core, using ICT as suits it.', 'Scottish DipHE holders have shown skills in gathering, critically analysing and presenting core information and data, using ICT as appropriate.', 'To be awarded a Diploma of Higher Education in Scotland, you will have shown that you can gather, critically analyse and present your subject\'s core information and data.')
s('4.13.b5', ['use', 'evaluate', 'formulate', 'identify'], 'evidence-based argument on defined problems', 'Uses knowledge, understanding and skills to judge critically and build evidence-based arguments, and to find solutions to defined, mostly routine problems.', 'Typical Scottish DipHE holders will be able to evaluate critically and build evidence-based arguments and find solutions to well-defined, mostly routine problems.', 'With a Diploma of Higher Education in Scotland, you will usually be able to build arguments from evidence and solve clearly defined, mostly routine problems.')
s('4.13.b6', ['communicate', 'using'], 'communicating with specialist techniques', 'Reports what study and other work found, accurately and dependably, drawing on several specialist techniques.', 'Typical Scottish DipHE holders will be able to report results accurately and reliably with a range of specialist techniques.', 'With a Diploma of Higher Education in Scotland, you will usually be able to report your results accurately, using your subject\'s specialist methods.')
s('4.13.b7', ['identify', 'address', 'undertake'], 'own learning needs and guided learning', 'Recognises and meets their own main learning needs in defined settings, and takes guided further learning in new areas.', 'Typical Scottish DipHE holders will be able to identify and meet their main learning needs in defined contexts and take guided learning in new areas.', 'With a Diploma of Higher Education in Scotland, you will usually be able to see what you need to learn, deal with it, and learn new things with guidance.')
s('4.13.b8', ['apply'], 'skills with some responsibility and initiative', 'Applies subject and transferable skills where the task and its decision criteria are largely clear but some personal responsibility and initiative is needed.', 'Typical Scottish DipHE holders will be able to apply their skills where the task is mostly well defined but some responsibility and initiative is needed.', 'With a Diploma of Higher Education in Scotland, you will usually be able to use your skills where tasks are mostly clear but you must show some initiative.')
# 4.14 bachelor's non-honours, SCQF 9
s('4.14.b1', ['informed'], 'broad and comparative knowledge, with depth', 'Knows the subject broadly and comparatively, its areas, uses and links, with detailed knowledge of a defined subject or a narrower specialism balanced by breadth, informed by current developments.', 'Scottish bachelor\'s (non-honours) holders have shown broad, comparative knowledge of the subject, with detail in a defined area or a balanced specialism, informed by current developments.', 'To be awarded a bachelor\'s degree without honours in Scotland, you will have shown broad knowledge of your subject and how its parts compare, with depth in one area and awareness of new developments.')
s('4.14.b2', ['developed'], 'critical understanding of theories and how knowledge develops', 'Understands critically the essential theories, principles and concepts and how the main methods of enquiry develop them, aware that knowledge is provisional.', 'Scottish bachelor\'s (non-honours) holders have shown critical understanding of essential theories and how enquiry develops them, and awareness that knowledge is provisional.', 'To be awarded a bachelor\'s degree without honours in Scotland, you will have shown that you understand your subject\'s main theories critically, how research builds them, and that knowledge can change.')
s('4.14.b3', [], 'competence in routine and some advanced practices', 'Is familiar and competent with routine materials, practices and skills and with a few more specialised, advanced and complex ones.', 'Scottish bachelor\'s (non-honours) holders have shown competence with routine materials and practices and a few specialised, advanced ones.', 'To be awarded a bachelor\'s degree without honours in Scotland, you will have shown that you handle everyday methods well and a few advanced ones too.')
s('4.14.b4', ['drawing', 'include'], 'well-developed skills with a wide range of sources', 'Has well-developed skills to gather, evaluate, analyse and present information and data from a wide range of current sources, using ICT as suits the subject.', 'Scottish bachelor\'s (non-honours) holders have shown well-developed skills in gathering, evaluating, analysing and presenting information from many current sources, ICT included.', 'To be awarded a bachelor\'s degree without honours in Scotland, you will have shown strong skills in finding, judging, analysing and presenting information from many current sources.')
s('4.14.b5', ['use', 'identifying', 'analysing', 'formulating', 'evaluating', 'applying'], 'identifying problems and evidence-based solutions', 'Uses knowledge, understanding and skills both to find and analyse problems and to build, test and apply evidence-based solutions and arguments.', 'Typical Scottish bachelor\'s (non-honours) holders will be able to identify and analyse problems and to formulate, evaluate and apply evidence-based solutions.', 'With a bachelor\'s degree without honours in Scotland, you will usually be able to spot and analyse problems and build and test solutions from evidence.')
s('4.14.b6', ['communicate', 'using'], 'communicating across contexts with the subject\'s concepts', 'Reports results accurately and reliably in a range of contexts, using the subject\'s main specialist concepts and techniques.', 'Typical Scottish bachelor\'s (non-honours) holders will be able to report results accurately in varied contexts using the main specialist concepts and techniques.', 'With a bachelor\'s degree without honours in Scotland, you will usually be able to report your results accurately in different settings, using your subject\'s key ideas and methods.')
s('4.14.b7', ['identify', 'address', 'draw'], 'own learning needs, drawing on current research', 'Recognises and meets their own learning needs, drawing on current research, development and professional materials.', 'Typical Scottish bachelor\'s (non-honours) holders will be able to identify and meet their learning needs, drawing on current research and professional materials.', 'With a bachelor\'s degree without honours in Scotland, you will usually be able to work out what you need to learn and use current research and professional materials to learn it.')
s('4.14.b8', ['apply'], 'skills with responsibility, initiative and decisions', 'Applies subject and transferable skills where task and criteria may be clear but responsibility, initiative and decision-making are also needed.', 'Typical Scottish bachelor\'s (non-honours) holders will be able to apply their skills where tasks may be well defined but responsibility, initiative and decisions are needed.', 'With a bachelor\'s degree without honours in Scotland, you will usually be able to use your skills where you must take responsibility, show initiative and make decisions.')
# 4.15 honours, FHEQ 6
s('4.15.b1', ['informed'], 'systematic understanding reaching the forefront', 'Understands key aspects of the field systematically, with coherent, detailed knowledge, some of it at or informed by the forefront of the discipline.', 'Honours graduates have shown systematic understanding of key aspects of the field and coherent, detailed knowledge, part of it at or near the discipline\'s forefront.', 'To be awarded an honours degree, you will have shown a systematic understanding of the key parts of your subject, with detailed knowledge that reaches its leading edge in places.')
s('4.15.b2', ['deploy'], 'accurate use of established techniques', 'Uses the discipline\'s established techniques of analysis and enquiry accurately.', 'Honours graduates have shown they can use the discipline\'s established techniques of analysis and enquiry accurately.', 'To be awarded an honours degree, you will have shown that you use your subject\'s standard methods of analysis and research accurately.')
s('4.15.b3.1', ['devise', 'sustain', 'solve', 'using'], 'arguing and solving problems with forefront ideas', 'Builds and keeps up arguments, or solves problems, drawing partly on forefront ideas and techniques.', 'Honours graduates\' conceptual understanding lets them build and sustain arguments or solve problems with ideas and techniques partly at the forefront.', 'To be awarded an honours degree, you will have shown that you can build and hold an argument, or solve a problem, using some of the newest ideas and methods.')
s('4.15.b3.2', ['describe', 'comment'], 'commenting on current research', 'Describes and comments on aspects of current research or advanced scholarship in the discipline.', 'Honours graduates\' conceptual understanding lets them describe and comment on aspects of current research or advanced scholarship.', 'To be awarded an honours degree, you will have shown that you can describe and comment on current research in your subject.')
s('4.15.b4', [], 'appreciating uncertainty and limits of knowledge', 'Appreciates that knowledge is uncertain, ambiguous and limited.', 'Honours graduates have shown they appreciate that knowledge is uncertain, ambiguous and limited.', 'To be awarded an honours degree, you will have shown that you understand knowledge is uncertain, open to more than one reading and limited.')
s('4.15.b5', ['manage', 'make'], 'managing own learning with scholarly and primary sources', 'Manages their own learning and uses scholarly reviews and primary sources, such as refereed articles or original materials.', 'Honours graduates have shown they can manage their own learning and use scholarly reviews and primary sources, such as refereed articles or original materials.', 'To be awarded an honours degree, you will have shown that you manage your own learning and use research reviews and original sources.')
s('4.15.b6', ['apply', 'learned', 'review', 'consolidate', 'extend', 'initiate', 'carry'], 'applying methods to extend knowledge; projects', 'Applies learned methods and techniques to review, consolidate, extend and apply knowledge, and to start and carry out projects.', 'Typical honours graduates will be able to use the methods they learned to review, consolidate, extend and apply knowledge, and to start and run projects.', 'With an honours degree, you will usually be able to use the methods you have learned to deepen and extend what you know, and to start and run projects.')
s('4.15.b7', ['evaluate', 'make', 'frame', 'achieve', 'identify'], 'critical evaluation and framing questions', 'Evaluates arguments, assumptions, abstract ideas and possibly incomplete data critically, judges, and frames questions that lead to one or several solutions.', 'Typical honours graduates will be able to critically evaluate arguments, assumptions, abstract concepts and incomplete data, judge, and frame questions that reach one or several solutions.', 'With an honours degree, you will usually be able to judge arguments, assumptions and patchy data critically, and ask the questions that lead to a solution or several.')
s('4.15.b8', ['communicate'], 'communicating to specialist and general audiences', 'Communicates information, ideas, problems and solutions to specialists and non-specialists.', 'Typical honours graduates will be able to communicate information, ideas, problems and solutions to specialist and non-specialist audiences.', 'With an honours degree, you will usually be able to explain ideas, problems and solutions to experts and non-experts.')
s('4.15.b9.1', [], 'initiative and personal responsibility', 'Employment needing initiative and personal responsibility.', 'Honours graduates will have the qualities and skills for work needing initiative and personal responsibility.', 'With an honours degree, you will have the qualities for work where you show initiative and take responsibility.')
s('4.15.b9.2', [], 'decisions in complex, unpredictable contexts', 'Employment needing decisions in complex and unpredictable contexts.', 'Honours graduates will have the qualities and skills for work needing decisions in complex, unpredictable contexts.', 'With an honours degree, you will have the qualities for work where you make decisions in complex, unpredictable situations.')
s('4.15.b9.3', ['needed', 'undertake'], 'learning ability for professional training', 'Employment needing the learning ability for further professional or equivalent training.', 'Honours graduates will have the learning ability to take further professional or equivalent training.', 'With an honours degree, you will have the ability to go on to professional training.')
# 4.16 honours, SCQF 10
s('4.16.b1', ['informed'], 'systematic, extensive, comparative knowledge; specialisms at the forefront', 'Knows and understands the subject as a whole systematically, extensively and comparatively, with its links, and a few specialisms in detail, some at or informed by the forefront.', 'Scottish honours graduates have shown systematic, extensive, comparative knowledge of the subject and its links, and detailed knowledge of a few specialisms partly at the forefront.', 'To be awarded an honours degree in Scotland, you will have shown wide, systematic knowledge of your whole subject and detail in a few specialisms that reach its leading edge.')
s('4.16.b2', [], 'critical understanding of theory and emerging issues', 'Understands critically the established theories, principles and concepts, and several advanced and emerging forefront issues.', 'Scottish honours graduates have shown critical understanding of established theories and of several advanced and emerging issues at the forefront.', 'To be awarded an honours degree in Scotland, you will have shown critical understanding of your subject\'s theories and of new questions at its leading edge.')
s('4.16.b3', ['developed', 'deploy'], 'limits of knowledge; established techniques', 'Understands critically how uncertain and limited knowledge is and how it develops, and can use established techniques of analysis and enquiry.', 'Scottish honours graduates have shown they understand critically that knowledge is uncertain and limited and how it develops, and can use established techniques of analysis and enquiry.', 'To be awarded an honours degree in Scotland, you will have shown that you understand the limits of knowledge and how it grows, and can use your subject\'s research methods.')
s('4.16.b4', [], 'comprehensive command of essential and advanced techniques', 'Knows comprehensively, and is familiar with, essential and advanced materials, techniques and skills, some at the forefront.', 'Scottish honours graduates have shown comprehensive knowledge of essential and advanced materials and techniques, some at the forefront.', 'To be awarded an honours degree in Scotland, you will have shown full command of your subject\'s essential and advanced methods, some of them the newest.')
s('4.16.b5', ['identifying'], 'identifying information needs and systematic gathering', 'Can identify information needs and systematically gather, analyse and interpret ideas and data from varied sources they have evaluated, current research among them.', 'Scottish honours graduates have shown skill in identifying information needs and systematically gathering and interpreting data from evaluated sources, including current research.', 'To be awarded an honours degree in Scotland, you will have shown that you work out what information you need, then gather and interpret it systematically from sources you have judged.')
s('4.16.b6', ['use', 'identifying', 'analysing', 'demonstrating', 'formulating', 'evaluating', 'applying'], 'systematic critical assessment with some originality', 'Uses knowledge and skills to assess concepts, ideas and possibly incomplete data systematically and critically, to find and analyse complex problems, showing some originality and creativity in building, testing and applying evidence-based solutions.', 'Typical Scottish honours graduates will be able to assess concepts and incomplete data systematically and critically, analyse complex problems and show some originality in evidence-based solutions.', 'With an honours degree in Scotland, you will usually be able to assess ideas and data critically, analyse complex problems and bring some original, creative thinking to solving them.')
s('4.16.b7', ['communicate', 'using'], 'communicating with the full repertoire of the subject', 'Reports results accurately and reliably, using the full range of the subject\'s principal concepts and constructs.', 'Typical Scottish honours graduates will be able to report results accurately using the full repertoire of the subject\'s principal concepts.', 'With an honours degree in Scotland, you will usually be able to report your work accurately, using all your subject\'s main ideas.')
s('4.16.b8', ['identify', 'address', 'making'], 'systematically meeting learning needs at the forefront', 'Recognises and meets their own learning needs systematically, in current and new areas, using research, development and professional materials, including those at the forefront.', 'Typical Scottish honours graduates will be able to identify and meet their learning needs systematically, in current and new areas, using research and professional materials up to the forefront.', 'With an honours degree in Scotland, you will usually be able to plan your own learning, in familiar and new areas, using the latest research and professional materials.')
s('4.16.b9.1', [], 'personal responsibility and initiative', 'Skills applied where personal responsibility and initiative are required.', 'Typical Scottish honours graduates will be able to apply their skills in professional settings that require personal responsibility and initiative.', 'With an honours degree in Scotland, you will usually be able to use your skills at work where you must take responsibility and show initiative.')
s('4.16.b9.2', [], 'decisions in complex, unpredictable contexts', 'Skills applied where decisions are needed in complex and unpredictable contexts.', 'Typical Scottish honours graduates will be able to apply their skills where decisions are made in complex, unpredictable contexts.', 'With an honours degree in Scotland, you will usually be able to use your skills where you must decide in complex, unpredictable situations.')
s('4.16.b9.3', ['undertake'], 'further professional development', 'Skills applied where further professional or equivalent development must be undertaken.', 'Typical Scottish honours graduates will be able to apply their skills where further professional development is required.', 'With an honours degree in Scotland, you will usually be able to use your skills where you must keep developing professionally.')
# 4.17 master's, FHEQ 7 and SCQF 11
s('4.17.b1', ['informed'], 'systematic understanding; critical awareness at the forefront', 'Understands knowledge systematically and is critically aware of current problems or new insights, much of it at or informed by the forefront of the discipline or practice.', 'Master\'s graduates have shown systematic understanding and critical awareness of current problems or new insights, much of it at or near the forefront.', 'To be awarded a master\'s degree, you will have shown systematic understanding and a critical grasp of current problems and new insights, much of it at the leading edge.')
s('4.17.b2', [], 'comprehensive understanding of research techniques', 'Understands comprehensively the techniques that apply to their own research or advanced scholarship.', 'Master\'s graduates have shown comprehensive understanding of the techniques for their own research or advanced scholarship.', 'To be awarded a master\'s degree, you will have shown full understanding of the methods your own research needs.')
s('4.17.b3', ['used', 'create', 'interpret'], 'originality in applying knowledge; how research creates knowledge', 'Applies knowledge with originality and understands in practice how established research techniques create and interpret knowledge.', 'Master\'s graduates have shown originality in applying knowledge and a practical grasp of how research techniques create and interpret knowledge.', 'To be awarded a master\'s degree, you will have shown originality in using what you know and a practical grasp of how research makes new knowledge.')
s('4.17.b4.1', ['evaluate'], 'critically evaluating current research', 'Evaluates current research and advanced scholarship critically.', 'Master\'s graduates\' conceptual understanding lets them critically evaluate current research and advanced scholarship.', 'To be awarded a master\'s degree, you will have shown that you can critically evaluate current research.')
s('4.17.b4.2', ['evaluate', 'develop', 'propose'], 'critiquing methodologies; proposing hypotheses', 'Evaluates and critiques methodologies and, where fitting, proposes new hypotheses.', 'Master\'s graduates\' conceptual understanding lets them critique methodologies and, where relevant, propose new hypotheses.', 'To be awarded a master\'s degree, you will have shown that you can critique research methods and, where it fits, put forward new hypotheses.')
s('4.17.b5', ['deal', 'make', 'communicate'], 'complex issues, judgement without complete data', 'Deals with complex issues systematically and creatively, judges soundly without complete data, and communicates conclusions clearly to specialists and non-specialists.', 'Typical master\'s graduates will be able to handle complex issues systematically and creatively, judge soundly on incomplete data and state conclusions clearly to any audience.', 'With a master\'s degree, you will usually be able to handle complex issues systematically and creatively, judge well without all the facts and explain your conclusions clearly.')
s('4.17.b6', ['demonstrate', 'tackling', 'solving', 'act', 'planning', 'implementing'], 'self-direction, originality and autonomy', 'Shows self-direction and originality in solving problems, and acts autonomously in planning and carrying out tasks at a professional level.', 'Typical master\'s graduates will be able to show self-direction and originality in solving problems and work autonomously in planning and doing professional tasks.', 'With a master\'s degree, you will usually be able to direct yourself, solve problems in original ways and plan and carry out professional work on your own.')
s('4.17.b7', ['continue', 'advance', 'develop'], 'continuing to advance knowledge and skills', 'Keeps advancing knowledge and understanding and develops new skills to a high level.', 'Typical master\'s graduates will be able to keep advancing their knowledge and develop new skills to a high level.', 'With a master\'s degree, you will usually be able to keep growing your knowledge and build new skills to a high level.')
s('4.17.b8.1', [], 'initiative and personal responsibility', 'Employment needing initiative and personal responsibility.', 'Master\'s graduates will have the qualities and skills for work needing initiative and personal responsibility.', 'With a master\'s degree, you will have the qualities for work where you show initiative and take responsibility.')
s('4.17.b8.2', [], 'decisions in complex, unpredictable situations', 'Employment needing decisions in complex and unpredictable situations.', 'Master\'s graduates will have the qualities and skills for work needing decisions in complex, unpredictable situations.', 'With a master\'s degree, you will have the qualities for work where you decide in complex, unpredictable situations.')
s('4.17.b8.3', ['required'], 'independent learning for continuing development', 'Employment needing the independent learning ability that continuing professional development requires.', 'Master\'s graduates will have the independent learning ability that continuing professional development requires.', 'With a master\'s degree, you will have the ability to keep learning independently throughout your career.')
# 4.18 doctorate, FHEQ 8 and SCQF 12
s('4.18.b1', ['satisfy', 'extend', 'merit'], 'creating new knowledge of publishable quality', 'Creates and interprets new knowledge, by original research or other advanced scholarship, good enough to pass peer review, extend the discipline\'s forefront and merit publication.', 'Doctoral graduates have shown they create and interpret new knowledge, by original research or advanced scholarship, good enough for peer review and publication and extending the forefront.', 'To be awarded a doctorate, you will have shown that you create new knowledge through original research, good enough to pass peer review, push your field forward and be published.')
s('4.18.b2', [], 'substantial body of knowledge at the forefront', 'Has acquired and understands systematically a substantial body of knowledge at the forefront of the discipline or professional practice.', 'Doctoral graduates have shown they have systematically acquired and understood a substantial forefront body of knowledge.', 'To be awarded a doctorate, you will have shown that you hold a large, systematic body of knowledge at your field\'s leading edge.')
s('4.18.b3', ['conceptualise', 'design', 'implement', 'adjust'], 'designing and adjusting research projects', 'Can conceive, design and carry out a project that generates new knowledge, applications or understanding at the forefront, and adjust its design when unforeseen problems arise.', 'Doctoral graduates have shown they can generally conceptualise, design and implement a project for new knowledge at the forefront, adjusting it when problems arise.', 'To be awarded a doctorate, you will have shown that you can plan, design and carry out a research project that creates new knowledge, and change course when problems arise.')
s('4.18.b4', [], 'detailed understanding of research techniques', 'Understands in detail the techniques for research and advanced academic enquiry that apply.', 'Doctoral graduates have shown detailed understanding of the techniques for research and advanced enquiry.', 'To be awarded a doctorate, you will have shown detailed understanding of the research methods your work needs.')
s('4.18.b5', ['make', 'communicate'], 'judgements on complex issues; communicating to all audiences', 'Makes informed judgements on complex specialist issues, often without complete data, and communicates ideas and conclusions clearly and effectively to specialists and non-specialists.', 'Typical doctoral graduates will be able to judge complex specialist issues in an informed way, often on incomplete data, and communicate them clearly to any audience.', 'With a doctorate, you will usually be able to judge complex issues in your field, often without all the facts, and explain your ideas clearly to anyone.')
s('4.18.b6', ['continue', 'undertake', 'contributing'], 'continuing advanced research and development', 'Continues to carry out advanced pure or applied research and development, contributing substantially to new techniques, ideas or approaches.', 'Typical doctoral graduates will be able to continue advanced pure or applied research and development, contributing substantially to new techniques, ideas or approaches.', 'With a doctorate, you will usually be able to keep doing advanced research and help create new techniques, ideas and approaches.')
s('4.18.b7', [], 'qualities for autonomous work in complex situations', 'Has the qualities and transferable skills for work needing personal responsibility and largely autonomous initiative in complex, unpredictable professional settings.', 'Doctoral graduates will have the qualities and transferable skills for work needing personal responsibility and largely autonomous initiative in complex, unpredictable settings.', 'With a doctorate, you will have the qualities for work where you take responsibility and act largely on your own initiative in complex, unpredictable situations.')

# SL level-language data. Keys are descriptor numbers, in the issuer's order (FHEQ and FQHEIS interleaved by level).
ORDER_D = ['4.10', '4.11', '4.12', '4.13', '4.14', '4.15', '4.16', '4.17', '4.18']
DEFINING = {  # what makes each level itself: our words; practitioner, student
 '4.10': ('Knowing the concepts beneath a subject and using basic theory to weigh data and argue soundly; choosing between approaches; learning further where the setting is managed for them.', 'At this first level, you know the main ideas behind your subject, can use them to weigh up evidence and make a sound case, and keep learning where the course is set out for you.'),
 '4.11': ('Outline knowledge of the subject with some areas in depth; routine techniques applied to routine problems in clearly bounded contexts; limited personal responsibility.', 'At this first Scottish level, you know your subject in outline and parts of it more fully, and you use standard methods on familiar problems where the task is clearly set.'),
 '4.12': ('Critical understanding of established principles and their history; applying them beyond the setting where they were learned; knowing the limits of one\'s own knowledge; starting critical analysis oneself.', 'At this level, you think critically about your field\'s established ideas, use them in new settings such as work, know where your knowledge stops, and start analysing problems yourself.'),
 '4.13': ('Detailed knowledge of some areas and a first awareness of the forefront; critical analysis of core data; evidence-based argument on clearly bounded problems; naming one\'s own learning needs.', 'At this Scottish level, you know some areas in detail, are aware of the big open questions, build arguments from evidence and can say what you still need to learn.'),
 '4.14': ('Broad, comparative knowledge, with a specialism informed by current developments; seeing knowledge as provisional; identifying and analysing problems and applying evidence-based solutions; drawing on current research to meet one\'s own learning needs.', 'At this Scottish level, you see your subject broadly and in comparison, know some of it in depth, accept that knowledge can change, and use current research to keep learning.'),
 '4.15': ('Systematic understanding with some knowledge at the forefront; accurate use of established techniques; commenting on current research; appreciating uncertainty and ambiguity; judging with incomplete data and framing the questions that lead to solutions; managing one\'s own learning from primary sources.', 'At honours level, you understand your field as a system, with parts of it at the leading edge, use its methods accurately, comment on current research, accept that knowledge is uncertain, and manage your own learning.'),
 '4.16': ('Systematic, extensive and comparative understanding of the whole subject, critical understanding of emerging issues and of how knowledge is made; the first call for some originality and creativity; professional contexts.', 'At Scottish honours level, you understand your whole subject and how knowledge in it is made, follow its newest questions, and begin to bring some originality and creativity of your own.'),
 '4.17': ('Much of one\'s knowledge at or informed by the forefront; originality in applying it; evaluating research and methodologies critically and proposing hypotheses; sound judgement without complete data; autonomy and self-direction at a professional level.', 'At master\'s level, much of what you know is at the leading edge; you apply it with originality, critique research and its methods, judge well without all the facts and work on your own at a professional level.'),
 '4.18': ('Creating new knowledge of publishable quality through original research; conceiving, designing and adjusting a project at the forefront; continuing to contribute new techniques and ideas; largely autonomous initiative.', 'At doctoral level, you create new knowledge through your own research, good enough to be published; you design and steer a project at the leading edge and go on contributing new ideas and methods.'),
}
